// Checkouts last updated between 61 and 91 minutes ago
// Running every 30 min means each checkout falls in this window exactly once
const now = Date.now();
const updatedAtMax = new Date(now - 61 * 60 * 1000).toISOString();
const updatedAtMin = new Date(now - 91 * 60 * 1000).toISOString();
return [{ json: { updatedAtMax, updatedAtMin } }];

const raw = $input.first().json;
const checkouts = Array.isArray(raw.checkouts) ? raw.checkouts : [];

const results = [];

for (const c of checkouts) {
  // Skip completed or paid checkouts
  if (c.completed_at) continue;
  if (!c.line_items || c.line_items.length === 0) continue;
  if (!c.abandoned_checkout_url) continue;

  const rawPhone = (c.phone || c.billing_address?.phone || c.shipping_address?.phone || '').replace(/\D/g, '').replace(/^0+/, '');
  const waPhone  = rawPhone.startsWith('91') ? rawPhone : (rawPhone.length === 10 ? '91' + rawPhone : '');
  const hasPhone = waPhone.length >= 12;
  const hasEmail = !!(c.email && c.email.includes('@'));

  if (!hasPhone && !hasEmail) continue;

  const firstName = c.customer?.first_name || c.billing_address?.first_name || c.shipping_address?.first_name || 'Valued Customer';
  const items     = c.line_items.map(i => i.title).filter(Boolean);
  const total     = c.total_price ? '₹' + parseFloat(c.total_price).toFixed(2) : '';

  results.push({ json: {
    checkoutToken: c.token,
    email:         c.email || '',
    phone:         waPhone,
    hasPhone,
    hasEmail,
    firstName,
    items,
    primaryItem:   items[0] || 'your items',
    bookList:      items.slice(0, 3).join(', ') + (items.length > 3 ? ` and ${items.length - 3} more` : ''),
    total,
    cartUrl:       c.abandoned_checkout_url,
    itemCount:     items.length
  }});
}

console.log(`Abandoned carts to notify: ${results.length}`);
return results;

